sect2.programlisting:
#!/bin/bash # Check disk usage and alert if above threshold
THRESHOLD=80 PARTITION="/" CURRENT=$(df -h $PARTITION | grep -vE '^Filesystem|tmpfs|cdrom' | awk '{print $5}' | cut -d'%' -f1)
if [ "$CURRENT" -gt "$THRESHOLD" ]; then echo "WARNING: Disk usage on $PARTITION is at ${CURRENT}%" # Send email alert echo "Disk usage critical: ${CURRENT}% on $PARTITION" | mail -s "Disk Alert" root@localhost fi

#!/bin/bash # Monitor Postfix queue size
THRESHOLD=50 QUEUESIZE=$(mailq | tail -1 | awk '{print $5}')
if [ "$QUEUESIZE" -gt "$THRESHOLD ]; then echo "WARNING: Mail queue has $QUEUESIZE messages" echo "Postfix queue size: $QUEUESIZE messages" | mail -s "Queue Alert" root@localhost fi

