sect3.programlisting:
#!/bin/bash
# Optimize Roundcube database tables

mysql -u root -pYOURPASSWORD roundcube <<EOF
OPTIMIZE TABLE session;
OPTIMIZE TABLE cache;
OPTIMIZE TABLE cache_index;
OPTIMIZE TABLE cache_messages;
EOF

sect3.screen:
$> mysql -u root -p roundcube
mysql> DELETE FROM session WHERE changed < NOW() - INTERVAL 7 DAY;
mysql> quit;

sect3.programlisting:
#!/bin/bash # Backup all mailboxes using dsync
BACKUP_HOST="root@backup.example.com"
for user in $(ls /home); do if [ -d "/home/$user/Maildir" ]; then echo "Backing up $user..." dsync -u $user backup $BACKUP_HOST -u $user if [ $? -ne 0 ]; then echo "ERROR: Backup failed for $user" fi fi done

sect2.programlisting:
#!/bin/bash # Check mail server service status
SERVICES="postfix dovecot apache2 mysql"
for service in $SERVICES; do if ! systemctl is-active --quiet $service; then echo "ALERT: $service is not running!" | \ mail -s "Service Down: $service" root@localhost fi done
